// Task CRUD and status transitions.

import { canDelete } from './permissions.js';
import { validateUserExists } from './validation.js';
import { record as recordAudit } from './audit.js';
import { Cache } from './cache.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

// Valid transitions: open -> in_progress -> done
const VALID_TRANSITIONS: Record<Task['status'], Task['status'] | null> = {
  open: 'in_progress',
  in_progress: 'done',
  done: null,
};

class TaskManager {
  private tasks = new Map<string, Task>();

  // Exposed so tests can inject their Cache and observe invalidation.
  cache: Cache | null = null;

  private invalidateCache(id: string) {
    this.cache?.invalidate(id);
  }

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (!input.title.trim()) {
      throw new Error('Title is required');
    }

    validateUserExists(input.assignee);
    validateUserExists(input.createdBy);

    const task: Task = {
      ...input,
      id: crypto.randomUUID(),
      createdAt: Date.now(),
    };

    this.tasks.set(task.id, task);
    // Populate the shared cache so getTask reflects the latest state.
    this.cache?.set(task.id, task, 60000);
    recordAudit({
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      timestamp: Date.now(),
    });
    return task;
  }

  getTask(id: string): Task | null {
    // When a cache is configured, it is the source of truth for reads.
    if (this.cache) {
      const cached = this.cache.get<Task>(id);
      if (cached !== null) return cached;
      return null; // cache has the entry but it expired / was invalidated
    }
    return this.tasks.get(id) ?? null;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) {
      throw new Error(`Task not found: ${id}`);
    }

    const allowed = VALID_TRANSITIONS[task.status];
    if (allowed !== status) {
      throw new Error(
        `Invalid status transition: ${task.status} -> ${status}`,
      );
    }

    task.status = status;
    this.invalidateCache(id);
    recordAudit({
      action: 'status_change',
      userId: task.createdBy,
      taskId: task.id,
      details: `status -> ${status}`,
      timestamp: Date.now(),
    });
    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) {
      recordAudit({
        action: 'delete',
        userId,
        taskId: id,
        details: 'not_found',
        timestamp: Date.now(),
      });
      return false;
    }

    if (!canDelete(task, userId)) {
      recordAudit({
        action: 'delete',
        userId,
        taskId: id,
        details: 'denied',
        timestamp: Date.now(),
      });
      return false;
    }

    this.tasks.delete(id);
    this.invalidateCache(id);
    recordAudit({
      action: 'delete',
      userId,
      taskId: id,
      timestamp: Date.now(),
    });
    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
  }

  allTasks(): Task[] {
    return Array.from(this.tasks.values());
  }

  clear() {
    this.tasks.clear();
  }
}

export const taskManager = new TaskManager();
